int[] twoSumIndeksy(int[] tab, int cel) {
    Map<Integer, Integer> widziane = new HashMap<>(); // wartosc -> indeks
    for (int i = 0; i < tab.length; i++) {
        int potrzeba = cel - tab[i];
        if (widziane.containsKey(potrzeba)) {
            return new int[] { widziane.get(potrzeba), i };
        }
        widziane.put(tab[i], i); // dodajemy PO sprawdzeniu - unikamy sparowania elementu z samym soba
    }
    return new int[0]; // brak rozwiazania
}

int liczbaPodtablicOSumie(int[] tab, int cel) {
    Map<Integer, Integer> licznikPrefixSum = new HashMap<>();
    licznikPrefixSum.put(0, 1); // PUSTY prefiks (suma=0) "wystapil" raz - kluczowe dla podtablic zaczynajacych sie od indeksu 0
    int prefixSum = 0, wynik = 0;
    for (int x : tab) {
        prefixSum += x;
        wynik += licznikPrefixSum.getOrDefault(prefixSum - cel, 0);
        licznikPrefixSum.merge(prefixSum, 1, Integer::sum);
    }
    return wynik;
}

